(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*14;
  const w1y = Math.cos(y*0.016-t*0.22)*20 + Math.sin(x*0.014+t*0.3)*14;
  const w2x = Math.sin((x+w1x)*0.009+t*0.15)*30 + Math.cos((y+w1y)*0.011-t*0.12)*20;
  const w2y = Math.cos((y+w1y)*0.01-t*0.17)*30 + Math.sin((x+w1x)*0.008+t*0.2)*20;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 75+Math.cos(t*0.35)*55, 0.075, 2.2, 0.8],
    [320+Math.cos(t*0.45)*110, 165+Math.sin(t*0.6)*55, 0.09, 1.8, 1.0],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 0.6],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4, 1.1],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 0.7],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.9],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.4+5)*50, 0.1, 1.6, 1.2],
    [420+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+1)*55, 0.07, 2.4, 0.5]
  ];
  let aS=0, iS=0, fS=0, n=src.length;
  for (const [sX,sY,f,sp,wt] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*wt;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.8)*wt;
    fS += Math.sin(d*f*1.4-t*sp*0.8+3.0)*wt*0.5;
  }
  const act=aS/n, inh=iS/n, fb=fS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*1.0))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25 + Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.055+t*1.5)*Math.cos(sy*0.045-t*1.2)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.5;
  const spiral = (sp1+sp2+sp3)*0.28;
  const cross = Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t)*0.4+Math.sin((sx*2-sy)*0.06-t*0.7)*0.3;
  const cell = Math.tanh(cross*1.8)*0.25;
  const rd1 = Math.tanh((act-inh*0.65+bg*0.25+spiral+fb*0.15)*2.0);
  const rd2 = Math.tanh((act*0.8-inh*0.5+bg*0.4+spiral*0.7-fb*0.2)*1.6);
  const reaction = rd1*0.7+rd2*0.3;
  const blend = reaction*0.8+cell*0.2;
  const v = blend*0.5+0.5;
  const edge = Math.abs(reaction);
  const glow = Math.max(0, 1-edge*2.5)*0.3;
  const vf = Math.min(1, v+glow);
  const pal = [
    [5,12,55],[10,45,95],[15,95,120],[25,150,130],
    [120,185,90],[210,190,60],[230,140,55],[210,85,60],
    [170,50,70],[100,25,65],[45,15,55],[5,12,55]
  ];
  const idx=vf*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.5;
  const eBoost = edge>0.65?1.12+glow*0.3:1.0+glow*0.2;
  const satShift = Math.sin(t*0.3+ang*0.5)*0.08;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const gray = (r0+g0+b0)/3;
  const sat = 1.0+satShift;
  const rf = gray+(r0-gray)*sat, gf = gray+(g0-gray)*sat, bf = gray+(b0-gray)*sat;
  return [
    Math.min(255, Math.max(0, rf*lum*eBoost))|0,
    Math.min(255, Math.max(0, gf*lum*eBoost))|0,
    Math.min(255, Math.max(0, bf*lum*eBoost))|0
  ];
}
